from collections import deque
H,W=8,15
def comp(cells, diag=False):
    s=set(cells); seen=set()
    for c in cells:
        if c in seen: continue
        q=deque([c]); seen.add(c); grp=set([c])
        while q:
            i,j=q.popleft()
            for di in(-1,0,1):
                for dj in(-1,0,1):
                    if not diag and abs(di)+abs(dj)!=1: continue
                    n=(i+di,j+dj)
                    if n in s and n not in seen: seen.add(n); q.append(n); grp.add(n)
        yield grp
ones=[(i,j) for i in range(H) for j in range(W) if inp[i][j]==1]
stay=set(stay); bec=set(bec)
for diag in (False,True):
